import (
	"fmt"
	"slices"
	"strings"
	"testing"

	"lectureflow/internal/model"
)

// hashFixtures are the lectures whose v1 hashes are pinned in
// testdata/v1_hashes.golden. The golden file was generated by the v1 code
// (before the v2 prompt changes) and must never be regenerated: it is the
// proof that an all-enforce glossary keeps every v1 hash (lead ruling 9,
// SPEC-v2 G5.5 "a prompt version change never makes a stage stale").
func hashFixtures(t *testing.T) map[string]LectureSnapshot {
	sample := sampleSnapshot(t)
	empty := clone(sample)
	empty.Terms = nil
	empty.Summary = ""
	return map[string]LectureSnapshot{"sample": sample, "empty": empty}
}

// v1HashLines lists every lecture-level hash of the fixtures, one per line.
func v1HashLines(t *testing.T, fixtures map[string]LectureSnapshot) string {
	var b strings.Builder
	names := make([]string, 0, len(fixtures))
	for name := range fixtures {
		names = append(names, name)
	}
	slices.Sort(names)
	for _, name := range names {
		lec := fixtures[name]
		fmt.Fprintf(&b, "%s summary %s\n", name, SummaryInputHash(lec))
		fmt.Fprintf(&b, "%s repair %s\n", name, RepairInputHash(lec))
		for _, x := range []int{0, 1, 3} {
			fmt.Fprintf(&b, "%s translate-stage x=%d %s\n", name, x, TranslateStageHash(lec, x))
			for i, h := range TranslateHashes(lec, x) {
				fmt.Fprintf(&b, "%s translate x=%d #%d %s\n", name, x, i, h)
			}
		}
	}
	return b.String()
}

// withV2Fields returns lec with every term explicitly enforce and the other
// v2 columns filled in: none of them may change a hash.
func withV2Fields(lec LectureSnapshot) LectureSnapshot {
	c := clone(lec)
	for i := range c.Terms {
		c.Terms[i].Tier = model.TierEnforce
		c.Terms[i].Locked = i%2 == 0
		c.Terms[i].CommonWord = i%3 == 0
		c.Terms[i].JanitorNote = "Proper noun."
		c.Terms[i].ZhSource = model.ZhSourceJanitor
	}
	return c
}

// TestV1HashesUnchanged: with an all-enforce glossary (tier "" or
// "enforce") the repair, translate, translate-stage and summary hashes are
// byte-identical to v1, whatever the prompt templates say (lead ruling 9).
func TestV1HashesUnchanged(t *testing.T) {
	fx := hashFixtures(t)
	golden(t, "v1_hashes.golden", v1HashLines(t, fx))
	for name, lec := range fx {
		fx[name] = withV2Fields(lec)
	}
	golden(t, "v1_hashes.golden", v1HashLines(t, fx))
	// the per-sentence hashes of the v1 golden test are the same file too
	var hashes strings.Builder
	for i := range fx["sample"].Sentences {
		fmt.Fprintf(&hashes, "%d %s\n", i, TranslateHash(fx["sample"], i, testX))
	}
	golden(t, "translate_hashes.golden", hashes.String())
}

// TestGlossaryHashText: the format-independent glossary text of the hashes
// is the v1 {glossary_lines} for enforce terms, with " [reference]" after
// each reference term (lead ruling 9).
func TestGlossaryHashText(t *testing.T) {
	lec := sampleSnapshot(t)
	v1 := "cache => 缓存\ncache line => 缓存行\nLRU\nset associative => 组相联\nwrite-back => 写回"
	if got := GlossaryHashText(lec.Terms); got != v1 {
		t.Errorf("all enforce:\n%q\nwant the v1 lines\n%q", got, v1)
	}
	if got := GlossaryHashText(nil); got != None {
		t.Errorf("no terms: %q", got)
	}
	lec.Terms[1].Tier = model.TierReference // cache
	lec.Terms[2].Tier = model.TierReference // LRU (no zh)
	want := "cache => 缓存 [reference]\ncache line => 缓存行\nLRU [reference]\nset associative => 组相联\nwrite-back => 写回"
	if got := GlossaryHashText(lec.Terms); got != want {
		t.Errorf("with reference terms:\n%q\nwant\n%q", got, want)
	}
	// a disabled term never appears, whatever its tier
	lec.Terms[4].Tier = model.TierReference
	if got := GlossaryHashText(lec.Terms); got != want {
		t.Errorf("disabled reference term listed: %q", got)
	}
}

// TestTierChangeChangesHashes: moving any enabled term to the reference
// tier (or back) changes the repair and translate hashes, so those stages
// become stale (SPEC-v2 G3.1); the summary hash never contains the glossary.
func TestTierChangeChangesHashes(t *testing.T) {
	base := sampleSnapshot(t)
	sum, rep := SummaryInputHash(base), RepairInputHash(base)
	stage := TranslateStageHash(base, testX)
	before := TranslateHashes(base, testX)
	for i, term := range base.Terms {
		lec := clone(base)
		lec.Terms[i].Tier = model.TierReference
		changed := term.Enabled // a disabled term is in no hash
		if SummaryInputHash(lec) != sum {
			t.Errorf("%s → reference: summary hash changed", term.En)
		}
		if got := RepairInputHash(lec) != rep; got != changed {
			t.Errorf("%s → reference: repair hash changed=%v, want %v", term.En, got, changed)
		}
		if got := TranslateStageHash(lec, testX) != stage; got != changed {
			t.Errorf("%s → reference: translate stage hash changed=%v, want %v", term.En, got, changed)
		}
		after := TranslateHashes(lec, testX)
		for j := range after {
			if got := after[j] != before[j]; got != changed {
				t.Errorf("%s → reference: hash of sentence %d changed=%v, want %v", term.En, j, got, changed)
			}
		}
		// back to enforce: the v1 hashes again
		lec.Terms[i].Tier = model.TierEnforce
		if RepairInputHash(lec) != rep || TranslateStageHash(lec, testX) != stage || !slices.Equal(TranslateHashes(lec, testX), before) {
			t.Errorf("%s back to enforce: hashes differ from the original", term.En)
		}
	}
}
